        :device_backup_communication_loss => self.device_backup_communication_loss&.to_message,
        :onvif_auth_enabled => self.onvif_auth_enabled&.to_message,
        :device_moved => self.device_moved&.to_message,
        :device_hit => self.device_hit&.to_message,
        :fan_error => self.fan_error&.to_message,
        :settings_updated => self.settings_updated&.to_message,
        :poe_budget_power_exceeded => self.poe_budget_power_exceeded&.to_message,
        :poe_port_power_exceeded => self.poe_port_power_exceeded&.to_message,
        :poe_port_enabled => self.poe_port_enabled&.to_message,
        :input_digital_line_activated => self.input_digital_line_activated&.to_message,
        :output_digital_line_activated => self.output_digital_line_activated&.to_message,
      }.compact
    end

    # @return [Symbol, nil] the member of the oneof +event_tag_case+ that is set: +:server_connection_loss+, +:tamper_opened+, +:video_scenario_triggered+, +:storage_error_detected+, +:storage_write_error_detected+, +:storage_powered_off_overheated+, +:storage_device_ejected+, +:set_storage_port_operation_mode_read_write+, +:set_storage_port_operation_mode_read_only+, +:storage_formatting_started+, +:storage_formatting_finished+, +:storage_formatting_failed+, +:video_export_prepared+, +:video_export_failed+, +:direct_export_requested+, +:set_archive_storage_device_write_mode_mirrored+, +:set_archive_storage_device_write_mode_round_robin+, +:archive_data_encryption_enabled+, +:fw_update_started+, +:fw_update_finished+, +:fw_update_failed+, +:auto_fw_update_started+, +:channel_disconnected+, +:channel_added+, +:external_power_loss+, +:ring_button_pressed+, +:power_low+, +:battery_disconnected+, +:hard_fault+, +:battery_temperature_out_of_range+, +:battery_temperature_out_of_range_overheat+, +:battery_temperature_out_of_range_overcool+, +:device_temperature_out_of_range_critical_high+, +:device_temperature_out_of_range_critical_low+, +:temporary_video_access_request_from_pro+, +:temporary_video_access_request_from_company+, +:temporary_video_access_denied_for_pro+, +:temporary_video_access_approved_to_company+, +:temporary_video_access_approved_to_pro+, +:temporary_video_access_denied_for_company+, +:motion_detected+, +:human_detected+, +:pet_detected+, +:car_detected+, +:line_crossed+, +:car_crossed_line+, +:human_crossed_line+, +:pet_crossed_line+, +:device_backup_communication_channel_added+, +:device_backup_communication_loss+, +:onvif_auth_enabled+, +:device_moved+, +:device_hit+, +:fan_error+, +:settings_updated+, +:poe_budget_power_exceeded+, +:poe_port_power_exceeded+, +:poe_port_enabled+, +:input_digital_line_activated+, +:output_digital_line_activated+
    def event_tag_case = ONEOFS.fetch(:event_tag_case).find { !public_send(it).nil? }
  end
end
